// Load performance prompt + media-optimization skill
const input = $input.first().json;
const context = {
  system_prompt: '{{ performance prompt }}',
  skill: '{{ media-optimization skill }}',
  marketing_objective: input.marketing_objective || '',
  target_audience: input.target_audience || {},
  product_service_category: input.product_service_category || '',
  current_budget_constraints: input.current_budget_constraints || {},
  platforms_of_interest: input.platforms_of_interest || [],
  campaign_duration: input.campaign_duration || '',
  query_id: input.query_id
};
return { json: context };

// Validate against performance-output schema
const response = $input.first().json;
const content = response.content?.[0]?.text || response.content || '{}';
let output;
try {
  output = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  output = { query_id: $json.query_id, error: 'Invalid JSON output' };
}
output.agent_name = 'performance';
output.model_used = 'claude-3-5-haiku-20241022';
return { json: output };
